actions.command:
python3 -c "import os, filecmp, py_compile, pathlib, sys; t=os.environ['TARGET_DIR']; o=os.environ['ORIGINAL_DIR'];
for d, dirs, files in os.walk(t):
    dirs[:] = [x for x in dirs if x not in ('.git', '__pycache__')]
    for f in files:
        if f.endswith('.py'):
            p=pathlib.Path(d)/f; rel=p.relative_to(t); q=pathlib.Path(o)/rel;
            if not q.exists() or not filecmp.cmp(p, q, shallow=False):
                py_compile.compile(str(p), doraise=True)
print('Syntax: OK')" && echo "=== 2. Diff summary (files changed vs original) ===" && diff -rq --exclude='*.pyc' --exclude='*.egg-info' --exclude='.git' "$ORIGINAL_DIR" "$TARGET_DIR" 2>/dev/null | grep -E '^(Files|Only in)' || echo '(no differences)'

